INSERT INTO `questions` (`id`, `question_pool_id`, `question_bank_id`, `uuid`, `question_type`, `question_text`, `image_path`, `options`, `correct_answer`, `marks`, `bloom_level`, `difficulty_level`, `learning_objective`, `explanation`, `source`, `created_by`, `metadata`, `status`, `usage_count`, `created_at`, `updated_at`) VALUES
(1, NULL, NULL, '816adb25-9a1c-4053-a60e-98080d79cccb', 'multiple_choice', 'What is the time complexity of searching in a balanced BST?', NULL, '[\"O(1)\", \"O(n)\", \"O(log n)\", \"O(n log n)\"]', '\"O(log n)\"', 1.00, 'understand', 'medium', NULL, NULL, 'manual', 5, NULL, 'draft', 0, '2026-01-09 10:41:22', '2026-01-09 10:41:22'),
(2, NULL, NULL, '33bf0de0-9150-45a3-b77d-4e0974eaa7a7', 'essay', 'Explain the difference between an Array and a Linked List.', NULL, NULL, '\"Narrative explanation required.\"', 1.00, 'understand', 'medium', NULL, NULL, 'manual', 5, NULL, 'draft', 0, '2026-01-09 10:41:22', '2026-01-09 10:41:22'),
(3, NULL, NULL, '45b2a8ca-f4f0-4645-82bb-3e2be97f6147', 'multiple_choice', 'Which data structure follows LIFO?', NULL, '[\"Queue\", \"Stack\", \"Tree\", \"Graph\"]', '\"Stack\"', 1.00, 'understand', 'medium', NULL, NULL, 'manual', 5, NULL, 'draft', 0, '2026-01-09 10:41:22', '2026-01-09 10:41:22'),
(46, NULL, NULL, '9f83da37-0011-462c-b18b-f6475845ce71', 'short_answer', 'What is the name for a step-by-step set of rules to solve a problem?', NULL, '[]', '\"Algorithm\"', 1.00, 'understand', 'medium', NULL, 'An algorithm is a clear list of steps to get an answer, like a recipe for a computer.', 'ai_generated', 5, NULL, 'draft', 0, '2026-01-11 13:15:42', '2026-01-11 13:15:42'),
(47, NULL, NULL, 'cd33b034-28d4-44ae-a9d4-edcf6d00772b', 'essay', 'Explain the main idea behind \'time complexity\' in your own words. Why do we care about it?', NULL, '[]', '\"Time complexity is about how fast an algorithm runs when you give it more data. We care because a slow algorithm can take too long with large amounts of information.\"', 1.00, 'understand', 'hard', NULL, 'It tells us how the run time grows as the input size grows. A good algorithm doesn\'t slow down too much when you give it more work.', 'ai_generated', 5, NULL, 'draft', 0, '2026-01-11 13:16:06', '2026-01-11 13:16:06'),
(48, NULL, NULL, 'f85c3d3c-8a99-4cc3-b86e-2eee9cd15c30', 'fill_blank', 'A data structure that lets you add items to one end and take them from the other end is called a ______.', NULL, '[]', '\"queue\"', 1.00, 'understand', 'medium', NULL, 'A queue works like a line of people: first in, first out (FIFO).', 'ai_generated', 5, NULL, 'draft', 0, '2026-01-11 13:16:36', '2026-01-11 13:16:36'),
(45, NULL, NULL, '81c3a4a0-c614-479a-8152-ef7fb99a6ab8', 'true_false', 'An AND logic gate gives a 1 output only when both inputs are 1. True or False?', NULL, '[\"True\", \"False\"]', '\"True\"', 1.00, 'understand', 'easy', NULL, 'That is the correct rule for an AND gate. It is like saying \'both A AND B must be true\'.', 'ai_generated', 5, NULL, 'draft', 0, '2026-01-11 13:15:42', '2026-01-11 13:15:42'),
(44, NULL, NULL, '6ed3312b-579b-4a0d-9c50-4a8db29fa1c7', 'multiple_choice', 'What is the base of the binary number system?', NULL, '[\"Base 2\", \"Base 10\", \"Base 16\", \"Base 8\"]', '\"Base 2\"', 1.00, 'understand', 'easy', NULL, 'Binary uses only two digits: 0 and 1. This is called base 2.', 'ai_generated', 5, NULL, 'draft', 0, '2026-01-11 13:15:42', '2026-01-11 13:15:42');
